def split_csv(line):
    fields = []
    i = 0

    while i <= len(line):
        # Start of a new field
        if i == len(line):
            # End of line
            fields.append('')
            break

        if line[i] == '"':
            # Quoted field
            field = ''
            i += 1
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what comes next
                        if i == len(line):
                            # End of line - valid
                            fields.append(field)
                            break
                        elif line[i] == ',':
                            # Comma - valid
                            fields.append(field)
                            i += 1
                            break
                        else:
                            # Invalid character after closing quote
                            return None
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Unquoted field
            field = ''
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field cannot contain quotes
                    return None
                field += line[i]
                i += 1

            fields.append(field)

            # Skip the comma if present
            if i < len(line) and line[i] == ',':
                i += 1
            elif i == len(line):
                break

    return fields

